(() => {
  const ID = 'core-shot';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, range, crosshair, hint, scoreEl, running = false, paused = false, score = 0, shots = 0, hits = 0, raf = 0, last = 0, angle = 0, callbacks = {}, initialized = false;
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function frame(time) { if (!running || paused) return; const dt = Math.min(.04, Math.max(0, (time - last) / 1000 || 0)); last = time; angle += dt * 2.8; crosshair.style.transform = `rotate(${Math.sin(angle) * 34}deg)`; raf = requestAnimationFrame(frame); }
  function fire() { if (!running || paused) return; shots += 1; const timing = Math.abs(Math.sin(angle)); const perfect = timing < .12; const hit = timing < .42; if (hit) { hits += 1; score += perfect ? 150 : 70; hint.textContent = perfect ? 'PERFECT IMPACT' : 'Попадание'; range.classList.toggle('is-perfect', perfect); haptic(perfect ? 'medium' : 'light'); } else { score = Math.max(0, score - 25); hint.textContent = 'Мимо. Предскажи будущую точку.'; haptic('heavy'); } scoreEl.textContent = score; if (shots >= 10) finish(); }
  function finish() { if (!running) return; running = false; cancelAnimationFrame(raf); const previous = shell().getStats(ID), result = shell().saveResult(ID, score, { bestHits: Math.max(previous.bestHits || 0, hits), lastResult: { score, shots, hits } }), reward = Math.max(1, Math.floor(score / 130)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score, metadata: { transactionId: `game:${ID}:run:${Date.now()}`, shots, hits, perfect: score >= 900 } }); shell().emit('core_shot_finished', { gameId: ID, score, shots, hits, reward }); shell().emit('game_finished', { gameId: ID, score, reward, shots, hits, accuracy: hits / shots }); shell().ResultScreen.show(screen.querySelector('[data-shot-result]'), { score, bestScore: result.bestScore, reward, newRecord: result.newRecord, title: hits >= 7 ? 'Точный<br>выстрел!' : 'Прицел<br>сбит', details: { hits: `${hits} / ${shots}`, accuracy: `${Math.round(hits / shots * 100)}%` } }); screen.querySelector('[data-shot-result]').hidden = false; }
  function start() { cancelAnimationFrame(raf); running = true; paused = false; score = 0; shots = 0; hits = 0; angle = 0; range.classList.remove('is-perfect'); screen.querySelector('[data-shot-start]').hidden = true; screen.querySelector('[data-shot-result]').hidden = true; screen.querySelector('[data-shot-pause]').textContent = 'Ⅱ'; scoreEl.textContent = '0'; shell().emit('core_shot_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); last = performance.now(); raf = requestAnimationFrame(frame); haptic('light'); }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-shot-start]').hidden = false; screen.querySelector('[data-shot-result]').hidden = true; const stats = shell().getStats(ID); screen.querySelector('[data-shot-menu-best]').textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { running = false; cancelAnimationFrame(raf); screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function pause() { if (!running) return; paused = !paused; screen.querySelector('[data-shot-pause]').textContent = paused ? '▶' : 'Ⅱ'; if (!paused) { last = performance.now(); raf = requestAnimationFrame(frame); } else cancelAnimationFrame(raf); shell().emit(paused ? 'game_paused' : 'game_resumed', { gameId: ID }); }
  function init() { if (initialized) return; initialized = true; screen = document.getElementById('coreShotScreen'); screen.innerHTML = `<div class="core-shot-inner"><header class="core-shot-hud"><button class="icon-button" data-shot-close aria-label="На главную">×</button><div class="core-shot-brand"><small>TELEPLAY · РЕАКЦИЯ</small><b>Core Shot</b></div><div class="core-shot-stat"><small>СЧЁТ</small><b data-shot-score>0</b></div><button class="icon-button" data-shot-pause aria-label="Пауза">Ⅱ</button></header><div class="shot-range"><span class="shot-target"></span><span class="shot-crosshair" data-shot-crosshair></span></div><p class="shot-hint" data-shot-hint>Нажми, когда траектория войдёт в центр</p><button class="play-button large shot-fire" data-shot-fire>ОГОНЬ</button></div><div class="start-panel" data-shot-start><span class="panel-kicker">TELEPLAY · РЕАКЦИЯ</span><h2>Core<br>Shot</h2><p>Предскажи будущую точку.<br>Попади точно в момент.</p><button class="play-button large" data-shot-start-button>Начать прицеливание</button><div class="record">Лучший результат: <b data-shot-menu-best>0</b></div></div><div class="start-panel result-panel" data-shot-result hidden><span class="panel-kicker" data-result="kicker">СЕРИЯ ЗАВЕРШЕНА</span><h2 data-result="title">Точный<br>выстрел!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Попадания <b data-result="hits">0 / 10</b></span><span>Точность <b data-result="accuracy">0%</b></span></div><button class="play-button large" data-shot-replay>Новый выстрел</button><button class="text-button" data-shot-home>На главную</button></div>`; range = screen.querySelector('.shot-range'); crosshair = screen.querySelector('[data-shot-crosshair]'); hint = screen.querySelector('[data-shot-hint]'); scoreEl = screen.querySelector('[data-shot-score]'); screen.querySelector('[data-shot-fire]').addEventListener('click', fire); screen.querySelector('[data-shot-start-button]').addEventListener('click', start); screen.querySelector('[data-shot-replay]').addEventListener('click', start); screen.querySelector('[data-shot-home]').addEventListener('click', close); screen.querySelector('[data-shot-close]').addEventListener('click', close); screen.querySelector('[data-shot-pause]').addEventListener('click', pause); document.addEventListener('visibilitychange', () => { if (document.hidden && !screen.hidden && running && !paused) pause(); }); }
  window.CoreShotGame = { init, open, hide, close, start, restart: start, pause, resume: () => { if (paused) pause(); }, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
